/usr/bin/bash -lc "mkdir -p run_trace/qza_extract_1/table run_trace/qza_extract_1/repseq run_trace/qza_extract_1/stats
for name in table repseq stats; do perl -MIO::Uncompress::Unzip -MFile::Path=make_path -MFile::Basename=dirname -e '
  my ("'$zip,$dest)=@ARGV;
  my $u=IO::Uncompress::Unzip->new($zip, MultiStream=>1) or die "open zip: $IO::Uncompress::Unzip::UnzipError'"\\n\";
  STREAM: while (1) {
    my "'$h=$u->getHeaderInfo();
    my $n=$h->{Name};
    die "unsafe member $n'"\\n\" if "'$n =~ m{(''^/|'"\\.\\.)};
    my "'$out="$dest/$n";
    if ($n =~ m{/$}) { make_path($out); }
    else {
      make_path(dirname($out));
      open my $fh, ">", $out or die "write $out: $!'"\\n\";
      binmode "'$fh;
      my $buf="";
      while ((my $r=$u->read($buf)) > 0) { print {$fh} $buf; }
      close $fh;
    }
    last STREAM unless $u->nextStream();
  }
'"' \"run_trace/galaxy_downloads/"'${name}.qza" "run_trace/qza_extract_1/${name}"; done
find run_trace/qza_extract_1 -maxdepth 4 -type f | sort | sed -n '"'1,160p'
printf '\\nTable data files:\\n'
find run_trace/qza_extract_1/table -type f | sort | while read f; do printf '%s\\t' \""'$f"; head -c 16 "$f" | od -An -tx1; done'

