/usr/bin/bash -lc "mkdir -p run_trace/qza_payloads
perl -MIO::Uncompress::Unzip -e '
my ("'$zip,$want,$out)=@ARGV;
my $z=IO::Uncompress::Unzip->new($zip) or die $IO::Uncompress::Unzip::UnzipError;
do {
  my $h=$z->getHeaderInfo();
  if ($h->{Name} eq $want) {
    open my $fh, ">", $out or die $!; binmode $fh;
    my $buf=""; while ((my $r=$z->read($buf)) > 0) { print {$fh} $buf; }
    close $fh; exit 0;
  } else {
    my $buf=""; while ($z->read($buf) > 0) {}
  }
