/usr/bin/bash -lc "mkdir -p final_answer
perl -e '
  use strict; use warnings;
  my ("'$fasta,$table,$out)=@ARGV;
  open my $fa, "<", $fasta or die $!;
  my (%seq,$id,$s);
  while (my $line=<$fa>) {
    chomp $line;
    if ($line =~ /''^>('"\\S+)/) {
      "'$seq{$id}=uc($s) if defined $id;
      ($id,$s)=($1,"");
    } else { $s .= $line if defined $id; }
  }
  $seq{$id}=uc($s) if defined $id;
  close $fa;
  open my $in, "<", $table or die $!;
  open my $of, ">", $out or die $!;
  my $header_done=0;
  while (my $line=<$in>) {
    chomp $line;
    next if $line eq "# Constructed from biom file";
    my @f=split /'"\\t/, "'$line, -1;
    if (!$header_done) {
      die "unexpected header $f[0]'"\\n\" unless "'$f[0] eq "#OTU ID";
      $f[0]="sequence";
      print $of join("'"\\t\", @f), \"\\n\";
      "'$header_done=1;
      next;
    }
    my $fid=shift @f;
    die "missing sequence for $fid'"\\n\" unless exists "'$seq{$fid};
    for my $v (@f) {
      die "bad count $v for $fid'"\\n\" unless "'$v =~ /''^'"\\d+(?:\\.0+)?"'$/;
      $v =~ s/'"\\.0+"'$//;
    }
    print $of join("'"\\t\", "'$seq{$fid}, @f), "'"\\n\";
  }
  close "'$in; close $of;
'"' run_trace/qza_payloads/dna-sequences.fasta run_trace/galaxy_downloads/feature_table.tsv final_answer/asv_abundance.tsv
printf 'Final dimensions: '; awk 'BEGIN{FS=\"\\t\"} NR==1{cols=NF} END{print NR \" rows x \" cols \" columns\"}' final_answer/asv_abundance.tsv
sed -n '1,3p' final_answer/asv_abundance.tsv | cut -f1-5"

